import { expect, test } from '@playwright/test';
import { mount, mounted, waitFor } from './helpers';

// HLS fixtures come from test-media/generate-hls.sh (served by the demo app under /media/hls);
// the growing, live and late playlists are generated by e2e/static-server.mjs on port 5198.

type HlsStats = { kind: string; variant: { resolution: string | null } | null; segmentsLoaded: number };
const hlsStats = () => (el.getStats() as { hls: HlsStats | null }).hls;
const generated = (kind: string, testId: string) =>
  `http://localhost:5198/hls-${kind}/${testId.replace(/[^\w-]/g, '')}-${Date.now()}/index.m3u8`;

for (const name of ['vod-ts', 'vod-fmp4', 'byterange', 'aes', 'aes-seqiv']) {
  test(`HLS ${name}: loads, plays, seeks and ends`, async ({ page }) => {
    await mount(page, 'pup-video', { src: `/media/hls/${name}/index.m3u8` });
    await waitFor(page, 'el.readyState >= 3');
    const meta = await page.evaluate(() => ({
      d: el.duration,
      w: (el as unknown as HTMLVideoElement).videoWidth,
      h: (el as unknown as HTMLVideoElement).videoHeight,
      seekable: [el.seekable.start(0), el.seekable.end(0)],
      stats: el.getStats(),
    }));
    expect(meta.d).toBeCloseTo(10, 1);
    expect(meta.seekable).toEqual([0, meta.d]);
    expect([meta.w, meta.h]).toEqual([640, 360]);
    expect(meta.stats.format).toBe('hls');
    expect(meta.stats.hls).toMatchObject({ kind: 'vod', variant: null });

    await page.evaluate(() => el.play());
    await page.waitForTimeout(1000);
    const t = await page.evaluate(() => el.currentTime);
    expect(t).toBeGreaterThan(0.6);
    expect(t).toBeLessThan(1.4);

    await page.evaluate(() => (el.currentTime = 5));
    await waitFor(page, 'window.events.includes("seeked")');
    const afterSeek = await page.evaluate(() => el.currentTime);
    expect(afterSeek).toBeGreaterThanOrEqual(5);
    expect(afterSeek).toBeLessThan(5.6);

    await page.evaluate(() => (el.currentTime = 9));
    await waitFor(page, 'el.ended', 10_000);
    expect(await page.evaluate(() => el.currentTime)).toBeGreaterThan(9.9);
    const ev = await page.evaluate(() => window.events);
    expect(ev.slice(-2)).toEqual(['pause', 'ended']);
    expect(ev).not.toContain('error');
  });
}

test('HLS master playlist picks the highest-bandwidth variant, or the capped one', async ({ page }) => {
  await mount(page, 'pup-video', { src: '/media/hls/master/master.m3u8' });
  await waitFor(page, 'el.readyState >= 1');
  expect(await page.evaluate(hlsStats)).toMatchObject({ kind: 'vod', variant: { resolution: '640x360' } });
  expect(await page.evaluate(() => (el as unknown as HTMLVideoElement).videoWidth)).toBe(640);

  await mount(page, 'pup-video', { src: '/media/hls/master/master.m3u8', 'hls-max-height': '200' });
  await waitFor(page, 'el.readyState >= 1');
  expect(await page.evaluate(hlsStats)).toMatchObject({ variant: { resolution: '320x180' } });
  expect(await page.evaluate(() => (el as unknown as HTMLVideoElement).videoWidth)).toBe(320);
});

test('HLS <source type="application/x-mpegURL"> is selected and played', async ({ page }) => {
  await mount(page, 'pup-video', {}, '', '<source src="/media/hls/vod-ts/index.m3u8" type="application/x-mpegURL">');
  await waitFor(page, 'el.readyState >= 3');
  expect(await page.evaluate(() => el.currentSrc)).toMatch(/vod-ts\/index\.m3u8$/);
});

test('HLS growing EVENT playlist: seekable grows, duration becomes finite at ENDLIST, then ends', async ({ page }, info) => {
  await mount(page, 'pup-video', { src: generated('growing', info.testId) });
  await waitFor(page, 'el.readyState >= 3');
  const start = await page.evaluate(() => ({ d: el.duration, seekable: [el.seekable.start(0), el.seekable.end(0)], kind: el.getStats().hls }));
  expect(start.d).toBe(Infinity);
  expect(start.seekable[0]).toBe(0);
  expect(start.seekable[1]).toBeGreaterThanOrEqual(4);
  expect(start.seekable[1]).toBeLessThan(10);
  expect(start.kind).toMatchObject({ kind: 'event' });

  await page.evaluate(() => el.play());
  await waitFor(page, `el.seekable.end(0) > ${start.seekable[1]}`, 10_000);
  await waitFor(page, 'Number.isFinite(el.duration)', 15_000);
  expect(await page.evaluate(() => el.duration)).toBeCloseTo(10, 1);
  expect(await page.evaluate(() => el.getStats().hls)).toMatchObject({ kind: 'vod' });
  // Playback continues through the discontinuity (timestamps restart at 6 s) to the end.
  await waitFor(page, 'el.ended', 20_000);
  expect(await page.evaluate(() => el.currentTime)).toBeGreaterThan(9.9);
  const ev = await page.evaluate(() => window.events);
  const changes = ev.filter((e) => e === 'durationchange').length;
  expect(changes).toBe(2);
  expect(ev).not.toContain('error');
});

test('HLS live playlist: starts near the edge, seekable follows the window, never ends', async ({ page }, info) => {
  await mount(page, 'pup-video', { src: generated('live', info.testId), controls: true });
  await waitFor(page, 'el.readyState >= 3');
  const start = await page.evaluate(() => ({ d: el.duration, t: el.currentTime, s: el.seekable.start(0), e: el.seekable.end(0) }));
  expect(start.d).toBe(Infinity);
  // Window of 4 x 2 s; playback starts 3 segments before its end.
  expect(start.e - start.s).toBeCloseTo(8, 0);
  expect(start.e - start.t).toBeCloseTo(6, 0);
  expect(await page.evaluate(hlsStats)).toMatchObject({ kind: 'live' });
  await expect(mounted(page).locator('pup-controls .live')).toHaveText('LIVE');

  await page.evaluate(() => el.play());
  await waitFor(page, `el.seekable.start(0) >= ${start.s + 4}`, 15_000);
  const later = await page.evaluate(() => ({ t: el.currentTime, s: el.seekable.start(0), ended: el.ended, error: el.error }));
  expect(later.t).toBeGreaterThan(start.t + 3);
  expect(later.ended).toBe(false);
  expect(later.error).toBeNull();
  // Seeks are clamped to the window.
  await page.evaluate(() => (el.currentTime = 0));
  await waitFor(page, '!el.seeking');
  expect(await page.evaluate(() => el.currentTime >= el.seekable.start(0) - 0.01)).toBe(true);
  expect(await page.evaluate(() => window.events)).not.toContain('ended');
});

test('HLS segment that is late recovers through waiting -> playing', async ({ page }, info) => {
  await mount(page, 'pup-video', { src: generated('late', info.testId) });
  await waitFor(page, 'el.readyState >= 3');
  await page.evaluate(() => el.play());
  await waitFor(page, 'el.ended', 30_000);
  const ev = await page.evaluate(() => window.events);
  const waiting = ev.indexOf('waiting');
  expect(waiting).toBeGreaterThan(-1);
  expect(ev.indexOf('playing', waiting)).toBeGreaterThan(waiting);
  expect(ev).not.toContain('error');
});

test('HLS SAMPLE-AES reports MEDIA_ERR_SRC_NOT_SUPPORTED', async ({ page }) => {
  await mount(page, 'pup-video', { src: '/media/hls/sample-aes/index.m3u8' });
  await waitFor(page, 'window.events.includes("error")');
  expect(await page.evaluate(() => [el.error?.code, el.networkState])).toEqual([4, 3]);
});
